export class GrabbleAdmin{constructor(state,env){this.state=state;this.env=env}async fetch(req){const u=new URL(req.url);if(u.pathname==='/config'&&req.method==='GET')return Response.json({dictionaryProvider:(await this.state.storage.get('config:dictionaryProvider'))||'datamuse'});if(u.pathname==='/config'&&req.method==='POST'){let x={};try{x=await req.json()}catch{}const provider=x.dictionaryProvider==='dictionaryapi'?'dictionaryapi':'datamuse';await this.state.storage.put('config:dictionaryProvider',provider);return Response.json({ok:true,dictionaryProvider:provider})}if(u.pathname.startsWith('/datamuse/')&&req.method==='GET'){const word=decodeURIComponent(u.pathname.slice('/datamuse/'.length)).trim().toLowerCase(),started=Date.now();if(!/^[a-z]{3,}$/.test(word))return Response.json({name:'Datamuse',word,valid:false,score:0,cached:false,source:'Datamuse',latencyMs:Date.now()-started});const key='datamuse:'+word,cached=await this.state.storage.get(key),score=valid=>valid?[...word].reduce((n,ch)=>n+(VALUE[ch]||0),0):0;let upstreamStatus=null;if(cached&&cached.expiresAt>Date.now())return Response.json({name:'Datamuse',word,valid:cached.valid,score:score(cached.valid),cached:true,source:'Datamuse',latencyMs:Date.now()-started});try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),3500),upstream=await fetch('https://api.datamuse.com/words?sp='+encodeURIComponent(word)+'&max=10',{signal:controller.signal,headers:{accept:'application/json'}});clearTimeout(timer);upstreamStatus=upstream.status;if(upstream.ok){const list=await upstream.json(),valid=Array.isArray(list)&&list.some(item=>String(item?.word||'').toLowerCase()===word&&!word.includes(' '));await this.state.storage.put(key,{valid,expiresAt:Date.now()+(valid?30:1)*86400000});return Response.json({name:'Datamuse',word,valid,score:score(valid),cached:false,source:'Datamuse',status:upstream.status,latencyMs:Date.now()-started})}}catch(error){return Response.json({name:'Datamuse',word,valid:null,score:null,cached:false,source:'Datamuse',error:String(error?.name||'request-failed'),latencyMs:Date.now()-started})}return Response.json({name:'Datamuse',word,valid:null,score:null,cached:false,source:'Datamuse',error:'bad-response',status:upstreamStatus,latencyMs:Date.now()-started})}if(u.pathname.startsWith('/dictionary/')&&req.method==='GET'){const word=decodeURIComponent(u.pathname.slice('/dictionary/'.length)).toLowerCase();if(!/^[a-z]{3,}$/.test(word))return Response.json({valid:false});const key='dictionary:'+word,cached=await this.state.storage.get(key);if(cached&&cached.expiresAt>Date.now())return Response.json({valid:cached.valid});try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),4000),upstream=await fetch('https://api.dictionaryapi.dev/api/v2/entries/en/'+encodeURIComponent(word),{signal:controller.signal});clearTimeout(timer);if(upstream.ok||upstream.status===404){const valid=upstream.ok;await this.state.storage.put(key,{valid,expiresAt:Date.now()+(valid?30:1)*86400000});return Response.json({valid})}}catch{}return Response.json({valid:null})}if((u.pathname==='/register'||u.pathname==='/heartbeat')&&req.method==='POST'){const x=await req.json();if(!x.code)return new Response('missing code',{status:400});await this.state.storage.put('room:'+x.code,{code:x.code,mode:x.mode||'single',players:Number(x.players||0),lastSeen:Date.now()});return Response.json({ok:true})}if(u.pathname==='/rooms'){const cutoff=Date.now()-30*60*1000;const entries=await this.state.storage.list({prefix:'room:'});const rooms=[];for(const [key,r] of entries){if(r.lastSeen<cutoff){await this.state.storage.delete(key);continue}rooms.push(r)}rooms.sort((a,b)=>b.lastSeen-a.lastSeen);return Response.json({rooms})}if(u.pathname.startsWith('/unregister/')&&req.method==='POST'){const c=decodeURIComponent(u.pathname.slice('/unregister/'.length)).toUpperCase();await this.state.storage.delete('room:'+c);return Response.json({ok:true})}if(u.pathname.startsWith('/kill/')&&req.method==='POST'){const c=u.pathname.split('/').pop().toUpperCase();await this.env.ROOMS.get(this.env.ROOMS.idFromName(c)).fetch('https://room/admin/kill',{method:'POST'});await this.state.storage.delete('room:'+c);return Response.json({ok:true})}return new Response('not found',{status:404})}}
